// ==UserScript==
// @name        真实世界 stat_data Schema
// @version     1.1.0
// @description 注册 stat_data zod schema for RealWorld 言灵穿越卡
// @author      RealWorld Project
// @match       *://*/*
// ==/UserScript==

(function() {
  'use strict';

  const StatDataSchema = z.object({
    user: z.object({
      name: z.string(),
      gender: z.enum(['男', '女']),
      birth_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      height: z.number().int().min(100).max(250),
      appearance: z.string(),
      clothing_style: z.string(),
      devices: z.object({
        phone: z.string(),
        laptop: z.string(),
      }).strict(),
      background: z.object({
        birthplace: z.string(),
        education: z.string(),
        current_status: z.string(),
        residence: z.string(),
      }).strict(),
      arrival_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    }).strict(),

    time: z.object({
      current_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      day_count: z.number().int().min(0),
    }).strict(),

    geass: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      name: z.string(),
      description: z.string(),
      type: z.string(),
      total_uses: z.number().int().min(0),
      use_history: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
        target: z.string(),
        effect_desc: z.string(),
      }).strict()),
    }).strict()),

    tasks: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      name: z.string(),
      type: z.enum(['主线', '支线', '日常', '机遇']),
      goal: z.string(),
      status: z.enum(['进行中', '已完成', '已失败']),
      created_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      deadline: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
    }).strict()),

    npc_relations: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      name: z.string(),
      relationship: z.string(),
      impression: z.number().int().min(-100).max(100),
      known_since: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      context: z.object({
        current_mood: z.string(),
        attitude_reason: z.string(),
        relationship_goal: z.string(),
        taboos: z.array(z.string()),
        unresolved_promises: z.array(z.string()),
      }).strict(),
    }).strict()),

    sexual: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      virgin: z.boolean(),
      virgin_exceptions: z.array(z.string()).optional(),
      body_count: z.number().int().min(0),
      relationship_status: z.string(),
      context: z.object({
        current_mood: z.string(),
        attitude_reason: z.string(),
        relationship_goal: z.string(),
        taboos: z.array(z.string()),
        unresolved_promises: z.array(z.string()),
      }).strict(),
      cycle: z.object({
        last_period_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
        cycle_length: z.number().int().min(1),
        period_length: z.number().int().min(1),
        phase: z.enum(['月经期', '卵泡期', '排卵期', '黄体期']),
      }).strict(),
      pregnancy: z.object({
        is_pregnant: z.boolean(),
        conception_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
        weeks: z.number().int().min(0).optional(),
        due_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
      }).strict(),
    }).strict()),

    reputation: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      value: z.number().int().min(-100).max(100),
      label: z.string(),
    }).strict()),

    world: z.object({
      known_regions: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        name: z.string(),
        description: z.string(),
        connections: z.array(z.string()),
      }).strict()),
      location_library: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        name: z.string(),
        region: z.string(),
        description: z.string(),
        visited_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
        notes: z.string(),
      }).strict()),
    }).strict(),

    situation: z.object({
      current: z.string(),
      opportunities: z.array(z.object({
        id: z.string(),
        name: z.string(),
        description: z.string(),
        suggestions: z.array(z.string()).max(5),
      }).strict()),
    }).strict(),

    items: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
      name: z.string(),
      quantity: z.number().int().min(0),
      description: z.string().optional(),
    }).strict()),

    assets: z.object({
      cash: z.number().min(0),
      bank: z.number().min(0),
      companies: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        name: z.string(),
        shares: z.string(),
      }).strict()),
      estates: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        name: z.string(),
        address: z.string(),
        area: z.string().optional(),
        value: z.number().optional(),
      }).strict()),
      vehicles: z.record(z.string().regex(/^[a-z]+_\d{3}$/), z.object({
        name: z.string(),
        plate: z.string(),
      }).strict()),
    }).strict(),

    _meta: z.object({
      schema_version: z.string(),
      uid_counters: z.record(z.string(), z.number().int().min(0)),
    }).strict(),
  });

  if (typeof registerMvuSchema === 'function') {
    registerMvuSchema('stat_data', StatDataSchema);
    console.log('[RealWorld] stat_data schema registered v1.1.0');
  } else {
    console.warn('[RealWorld] registerMvuSchema not available — MVU not loaded?');
  }
})();

// ==UserScript==
// @name        真实世界·状态栏桥接
// @version     1.0.0
// @description postMessage 桥接：接收状态栏 iframe 请求，推送 MVU 数据
// @author      RealWorld Project
// ==/UserScript==

(function() {
  'use strict';

  var NAME = '[RealWorld SB-Bridge]';
  var SB_SELECTOR = 'iframe[src*="statusbar"]';

  function getStatData() {
    try {
      if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
        var data = Mvu.getMvuData({type:'message', message_id:'latest'});
        if (data && data.stat_data) return data.stat_data;
        var chatData = Mvu.getMvuData({type:'chat'});
        if (chatData) return chatData;
      }
    } catch(e) {}
    try {
      if (typeof getVariables === 'function') {
        var v = getVariables({type:'message'});
        if (v && v.stat_data) return v.stat_data;
        return v;
      }
    } catch(e) {}
    return null;
  }

  function pushToStatusbar() {
    var sd = getStatData();
    if (!sd) return;
    var msg = {type:'sb-data', stat_data:sd};
    var iframes = document.querySelectorAll(SB_SELECTOR);
    for (var i = 0; i < iframes.length; i++) {
      try {
        iframes[i].contentWindow.postMessage(msg, '*');
      } catch(e) {}
    }
  }

  function handleMessage(e) {
    if (!e.data || e.data.type !== 'sb-getData') return;
    // Verify the source is a statusbar iframe
    var iframes = document.querySelectorAll(SB_SELECTOR);
    var fromSB = false;
    for (var i = 0; i < iframes.length; i++) {
      if (iframes[i].contentWindow === e.source) { fromSB = true; break; }
    }
    if (!fromSB) return;
    pushToStatusbar();
  }

  function init() {
    window.addEventListener('message', handleMessage);

    // Push data on MVU events
    if (typeof Mvu !== 'undefined') {
      Mvu.on('mag_variable_initiailized', function() {
        setTimeout(pushToStatusbar, 1500);
      });
      Mvu.on('mag_variable_update_ended', function() {
        setTimeout(pushToStatusbar, 800);
      });
      console.log(NAME, 'Bridge active (MVU events)');
    } else if (typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        Mvu.on('mag_variable_initiailized', function() {
          setTimeout(pushToStatusbar, 1500);
        });
        Mvu.on('mag_variable_update_ended', function() {
          setTimeout(pushToStatusbar, 800);
        });
        console.log(NAME, 'Bridge active (deferred MVU)');
      }).catch(function() {
        console.warn(NAME, 'Mvu not available, polling mode');
        // Fallback: poll for data
        setInterval(pushToStatusbar, 5000);
      });
    } else {
      console.warn(NAME, 'No Mvu, polling mode');
      setInterval(pushToStatusbar, 5000);
    }

    // Initial push after DOM settles
    setTimeout(pushToStatusbar, 3000);
  }

  // Wait for DOM
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(init, 2000);
    });
  } else {
    init();
  }
})();

// ==UserScript==
// @name        真实世界·变量守卫
// @version     1.0.0
// @description 自动验证 stat_data 完整性，检测数据异常
// @author      RealWorld Project
// ==/UserScript==

(function() {
  'use strict';

  var NAME = '[RealWorld Guardian]';
  var VALIDATION_ENABLED = true;

  function getStatData() {
    try {
      if (typeof getMvuData === 'function') return getMvuData('latest');
      if (typeof getVariables === 'function') return getVariables();
    } catch (e) {}
    return null;
  }

  function validate() {
    if (!VALIDATION_ENABLED) return;

    var data = getStatData();
    if (!data) return;

    var issues = [];

    // 1. Required fields
    if (!data.user || !data.user.name) issues.push('user.name 为空');
    if (!data.time || !data.time.current_date) issues.push('time.current_date 为空');
    if (!data.situation || !data.situation.current) issues.push('situation.current 为空');
    if (!data._meta || !data._meta.schema_version) issues.push('_meta.schema_version 缺失');

    // 2. Asset validation
    if (data.assets) {
      if (typeof data.assets.cash !== 'number' || data.assets.cash < 0) issues.push('assets.cash 无效');
      if (typeof data.assets.bank !== 'number' || data.assets.bank < 0) issues.push('assets.bank 无效');
      if (typeof data.assets.companies !== 'object') issues.push('assets.companies 非对象');
      if (typeof data.assets.estates !== 'object') issues.push('assets.estates 非对象');
      if (typeof data.assets.vehicles !== 'object') issues.push('assets.vehicles 非对象');
    }

    // 3. Impression range check
    if (data.npc_relations) {
      Object.keys(data.npc_relations).forEach(function(k) {
        var r = data.npc_relations[k];
        if (r.impression !== undefined) {
          if (r.impression < -100 || r.impression > 100) {
            issues.push((r.name || k) + ': impression=' + r.impression + ' 超出 [-100,100]');
          }
        }
        if (!r.context || !r.context.taboos || !r.context.unresolved_promises) {
          issues.push((r.name || k) + ': context 字段不完整');
        }
      });
    }

    // 4. virgin vs body_count consistency
    if (data.sexual) {
      Object.keys(data.sexual).forEach(function(k) {
        var s = data.sexual[k];
        if (s.virgin && s.body_count > 0) {
          issues.push((s.name || k) + ': virgin=true 但 body_count=' + s.body_count);
        }
      });
    }

    // 5. UID counter consistency
    if (data._meta && data._meta.uid_counters) {
      var counters = data._meta.uid_counters;
      var sections = {
        geass: data.geass,
        tasks: data.tasks,
        npc_relations: data.npc_relations,
        sexual: data.sexual,
        reputation: data.reputation,
        items: data.items
      };
      Object.keys(sections).forEach(function(prefix) {
        var entries = sections[prefix] || {};
        var actual = Object.keys(entries).length;
        var counter = counters[prefix] !== undefined ? counters[prefix] : 0;
        if (counter < actual) {
          issues.push(prefix + ': 计数器=' + counter + ' 但实际=' + actual);
        }
      });
    }

    // 6. Date format
    var dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (data.time && data.time.current_date && !dateRegex.test(data.time.current_date)) {
      issues.push('time.current_date 格式异常: ' + data.time.current_date);
    }

    if (issues.length > 0) {
      var msg = 'stat_data 发现 ' + issues.length + ' 个问题:\n' + issues.slice(0, 6).join('\n');
      if (issues.length > 6) msg += '\n...及其他 ' + (issues.length - 6) + ' 项';
      if (typeof toastr === 'object' && toastr.warning) {
        toastr.warning(msg.replace(/\n/g, '<br>'), '⚠ 变量守卫', { timeOut: 10000, extendedTimeOut: 5000 });
      }
      console.warn(NAME, 'Issues:', issues);
    }
  }

  // ---- init ----
  (function init() {
    if (typeof Mvu === 'undefined' && typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        Mvu.on('mag_variable_update_ended', validate);
        Mvu.on('mag_variable_initiailized', validate);
        console.log(NAME, 'Guardian active');
        // Run initial check
        setTimeout(validate, 2000);
      }).catch(function() {
        console.warn(NAME, 'Mvu not available');
      });
    } else if (typeof Mvu !== 'undefined') {
      Mvu.on('mag_variable_update_ended', validate);
      Mvu.on('mag_variable_initiailized', validate);
      console.log(NAME, 'Guardian active');
      setTimeout(validate, 2000);
    } else {
      console.warn(NAME, 'Mvu not found, retrying...');
      setTimeout(init, 3000);
    }
  })();
})();

// ==UserScript==
// @name        真实世界·数据检测器
// @version     1.0.0
// @description 深度检测 stat_data 完整性，提供诊断报告
// @author      RealWorld Project
// ==/UserScript==

(function() {
  'use strict';

  var NAME = '[RealWorld Detector]';

  function getStatData() {
    try {
      if (typeof getMvuData === 'function') return getMvuData('latest');
      if (typeof getVariables === 'function') return getVariables();
    } catch (e) {}
    return null;
  }

  function runCheck(verbose) {
    var data = getStatData();
    if (!data) {
      if (verbose) console.warn(NAME, 'stat_data 不存在');
      return [];
    }

    var issues = [];

    // 1. Required fields
    var required = ['user', 'time', 'situation', '_meta', 'assets'];
    required.forEach(function(f) {
      if (!data[f] || (typeof data[f] === 'object' && Object.keys(data[f]).length === 0)) {
        issues.push('MISSING: ' + f);
      }
    });

    // 2. Numbers
    if (data.time && typeof data.time.day_count !== 'number') {
      issues.push('TYPE: time.day_count 非数字');
    }

    // 3. Impression bounds
    if (data.npc_relations) {
      Object.keys(data.npc_relations).forEach(function(k) {
        var r = data.npc_relations[k];
        if (r.impression !== undefined && (r.impression < -100 || r.impression > 100)) {
          issues.push('IMPRESSION_OOB: ' + (r.name || k) + '=' + r.impression);
        }
        if (!r.context) issues.push('MISSING_CONTEXT: ' + (r.name || k));
        if (!r.known_since) issues.push('MISSING_KNOWN_SINCE: ' + (r.name || k));
      });
    }

    // 4. virgin/body_count mismatch
    if (data.sexual) {
      Object.keys(data.sexual).forEach(function(k) {
        var s = data.sexual[k];
        if (s.virgin && s.body_count > 0) {
          issues.push('VIRGIN_BC: ' + (s.name || k) + ' virgin=' + s.virgin + ' body_count=' + s.body_count);
        }
      });
    }

    // 5. Counter consistency
    if (data._meta && data._meta.uid_counters) {
      var counters = data._meta.uid_counters;
      var sections = { geass: data.geass, tasks: data.tasks, npc_relations: data.npc_relations, sexual: data.sexual, reputation: data.reputation, items: data.items, companies: data.assets ? data.assets.companies : {}, estates: data.assets ? data.assets.estates : {}, vehicles: data.assets ? data.assets.vehicles : {} };
      Object.keys(sections).forEach(function(p) {
        var entries = sections[p] || {};
        var actual = Object.keys(entries).length;
        var counter = counters[p] !== undefined ? counters[p] : 0;
        if (counter < actual) issues.push('COUNTER: ' + p + ' count=' + counter + ' actual=' + actual);
      });
    }

    // 6. Asset values
    if (data.assets) {
      if (typeof data.assets.cash !== 'number' || data.assets.cash < 0) issues.push('ASSET: cash=' + data.assets.cash);
      if (typeof data.assets.bank !== 'number' || data.assets.bank < 0) issues.push('ASSET: bank=' + data.assets.bank);
    }

    // 7. Date format
    var dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (data.time && data.time.current_date && !dateRegex.test(data.time.current_date)) {
      issues.push('DATE: ' + data.time.current_date);
    }
    if (data.user && data.user.birth_date && !dateRegex.test(data.user.birth_date)) {
      issues.push('BIRTH_DATE: ' + data.user.birth_date);
    }

    // 8. Items format
    if (data.items) {
      Object.keys(data.items).forEach(function(k) {
        var item = data.items[k];
        if (item.quantity !== undefined && (typeof item.quantity !== 'number' || item.quantity < 0)) {
          issues.push('ITEM_QTY: ' + (item.name || k) + ' quantity=' + item.quantity);
        }
      });
    }

    if (verbose) {
      if (issues.length > 0) {
        var report = 'stat_data 检测报告\n发现 ' + issues.length + ' 个问题:\n' + issues.join('\n');
        console.warn(NAME, '\n' + report);
        if (typeof toastr === 'object' && toastr.warning) {
          toastr.warning(report.replace(/\n/g, '<br>'), '🔍 数据检测', { timeOut: 12000, extendedTimeOut: 5000 });
        }
      } else {
        console.log(NAME, '无异常 ✓');
        if (typeof toastr === 'object' && toastr.success) {
          toastr.success('stat_data 无异常', '✅ 数据检测', { timeOut: 3000 });
        }
      }
    }

    return issues;
  }

  function runFullCheck() {
    runCheck(true);
  }

  // ---- init ----
  (function init() {
    if (typeof registerSlashCommand === 'function') {
      registerSlashCommand('stat_check', runFullCheck, ['stat_check'], '运行 stat_data 完整性检测');
    }

    // Run a lightweight check after each update
    if (typeof Mvu === 'undefined' && typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        Mvu.on('mag_variable_update_ended', function() {
          var issues = runCheck(false);
          if (issues.length > 0) {
            console.log(NAME, '更新后检测发现 ' + issues.length + ' 个问题');
          }
        });
        console.log(NAME, 'Detector active');
        setTimeout(function() { runCheck(true); }, 3000);
      }).catch(function() { console.warn(NAME, 'Mvu not available, /stat_check still works'); });
    } else if (typeof Mvu !== 'undefined') {
      Mvu.on('mag_variable_update_ended', function() {
        var issues = runCheck(false);
        if (issues.length > 0) console.log(NAME, 'Post-update issues:', issues.length);
      });
      console.log(NAME, 'Detector active');
      setTimeout(function() { runCheck(true); }, 3000);
    } else {
      console.log(NAME, 'Detector active (/stat_check only)');
    }
  })();
})();

// ==UserScript==
// @name        真实世界·变量观察器
// @version     1.0.0
// @description 监控 stat_data 变更，日志与调试
// @author      RealWorld Project
// ==/UserScript==

(function() {
  'use strict';

  var NAME = '[RealWorld Observer]';
  var initFired = false;
  var changeLog = [];
  var MAX_LOG = 50;

  function getStatData() {
    try {
      if (typeof getMvuData === 'function') return getMvuData('latest');
      if (typeof getVariables === 'function') return getVariables();
    } catch (e) {}
    return null;
  }

  function logChange(type, summary) {
    var data = getStatData();
    var ctx = '';
    if (data && data.time) {
      ctx = 'day=' + data.time.day_count + ' date=' + data.time.current_date;
    }
    changeLog.push({
      ts: new Date().toLocaleTimeString(),
      type: type,
      summary: summary,
      context: ctx
    });
    if (changeLog.length > MAX_LOG) changeLog.shift();
  }

  function onInit(variables) {
    if (initFired) return;
    initFired = true;
    var msg = 'stat_data 已初始化';
    logChange('INIT', msg);
    console.log(NAME, msg, variables ? Object.keys(variables).join(', ') : '');
    if (typeof toastr === 'object' && toastr.info) {
      toastr.info('变量系统已就绪', '🔄 真实世界', { timeOut: 3000 });
    }
  }

  function onUpdateStart(patches) {
    if (!patches || patches.length === 0) return;
    var paths = patches.map(function(p) { return p.path; }).join(', ');
    logChange('UPDATE_START', patches.length + ' patches: ' + paths.slice(0, 80));
    console.log(NAME, 'Update patches:', patches);
  }

  function onUpdateEnd() {
    var data = getStatData();
    if (data && data.time) {
      logChange('UPDATE_END', 'day=' + data.time.day_count + ' @ ' + data.time.current_date);
    }
  }

  function dumpState() {
    var data = getStatData();
    if (data) {
      var summary = Object.keys(data).join(', ');
      console.log('=== stat_data dump ===');
      console.log(JSON.stringify(data, null, 2));
      console.log('=== end dump (keys: ' + summary + ') ===');
      if (typeof toastr === 'object' && toastr.success) {
        toastr.success('已输出到控制台 (F12)', '📋 stat_data dump', { timeOut: 3000 });
      }
    } else {
      console.warn(NAME, 'stat_data 不存在');
      if (typeof toastr === 'object' && toastr.warning) {
        toastr.warning('stat_data 不存在', '📋 dump', { timeOut: 2000 });
      }
    }
  }

  function showLog() {
    if (changeLog.length === 0) {
      if (typeof toastr === 'object' && toastr.info) {
        toastr.info('尚无变更记录', '📋 变更日志', { timeOut: 2000 });
      }
      return;
    }
    var recent = changeLog.slice(-10);
    var text = '最近 ' + recent.length + ' 条记录:\n' + recent.map(function(e) {
      return e.ts + ' [' + e.type + '] ' + e.summary + (e.context ? ' (' + e.context + ')' : '');
    }).join('\n');
    console.log(NAME + '\n' + text);
    if (typeof toastr === 'object' && toastr.info) {
      toastr.info(text.slice(0, 200).replace(/\n/g, '<br>'), '📋 变更日志', { timeOut: 5000, extendedTimeOut: 3000 });
    }
  }

  // ---- init ----
  (function init() {
    // Register slash commands
    if (typeof registerSlashCommand === 'function') {
      registerSlashCommand('stat_dump', dumpState, ['stat_dump'], '输出 stat_data 到控制台');
      registerSlashCommand('stat_log', showLog, ['stat_log'], '显示 stat_data 变更日志');
    }

    if (typeof Mvu === 'undefined' && typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        Mvu.on('mag_variable_initiailized', onInit);
        Mvu.on('mag_variable_update_started', onUpdateStart);
        Mvu.on('mag_variable_update_ended', onUpdateEnd);
        console.log(NAME, 'Observer active');
        // Check if already initialized
        var data = getStatData();
        if (data && data.time && data.time.day_count !== undefined) {
          onInit(data);
        }
      }).catch(function() { console.warn(NAME, 'Mvu not available'); });
    } else if (typeof Mvu !== 'undefined') {
      Mvu.on('mag_variable_initiailized', onInit);
      Mvu.on('mag_variable_update_started', onUpdateStart);
      Mvu.on('mag_variable_update_ended', onUpdateEnd);
      console.log(NAME, 'Observer active');
      var data = getStatData();
      if (data && data.time && data.time.day_count !== undefined) {
        onInit(data);
      }
    } else {
      console.log(NAME, 'Observer active (commands only)');
    }
  })();
})();
